import { test, expect } from '@playwright/test';

test.describe('Expired Promo Code Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
    await page.waitForLoadState('networkidle');
  });

  test('should display error message when entering an expired promo code', async ({ page }) => {
    // Fill in required checkout fields
    await page.getByLabel('Email').fill('test@example.com');
    await page.getByLabel('Full Name').fill('John Doe');
    await page.getByLabel('Address').fill('123 Main St');
    await page.getByLabel('City').fill('New York');
    await page.getByLabel('State').fill('NY');
    await page.getByLabel('Zip Code').fill('10001');

    // Enter expired promo code
    const promoCodeInput = page.getByLabel('Promo Code');
    await promoCodeInput.fill('EXPIRED2020');

    // Click apply button
    await page.getByRole('button', { name: /apply/i }).click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/promo code expired|code is no longer valid/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should show error with specific expired code format', async ({ page }) => {
    // Fill in required checkout fields
    await page.getByLabel('Email').fill('user@test.com');
    await page.getByLabel('Full Name').fill('Jane Smith');
    await page.getByLabel('Address').fill('456 Oak Ave');
    await page.getByLabel('City').fill('Los Angeles');
    await page.getByLabel('State').fill('CA');
    await page.getByLabel('Zip Code').fill('90001');

    // Enter another expired promo code
    const promoCodeInput = page.getByLabel('Promo Code');
    await promoCodeInput.fill('SUMMER2021');

    // Click apply button
    await page.getByRole('button', { name: /apply/i }).click();

    // Verify error message appears
    const errorAlert = page.getByRole('alert');
    await expect(errorAlert).toBeVisible();
    await expect(errorAlert).toContainText(/expired/i);
  });

  test('should clear error message when entering a valid promo code after expired one', async ({ page }) => {
    // Fill in required checkout fields
    await page.getByLabel('Email').fill('valid@test.com');
    await page.getByLabel('Full Name').fill('Bob Johnson');
    await page.getByLabel('Address').fill('789 Pine Rd');
    await page.getByLabel('City').fill('Chicago');
    await page.getByLabel('State').fill('IL');
    await page.getByLabel('Zip Code').fill('60601');

    // Enter expired promo code first
    const promoCodeInput = page.getByLabel('Promo Code');
    await promoCodeInput.fill('EXPIRED2020');
    await page.getByRole('button', { name: /apply/i }).click();

    // Verify error is shown
    const errorMessage = page.getByText(/promo code expired|code is no longer valid/i);
    await expect(errorMessage).toBeVisible();

    // Clear and enter valid promo code
    await promoCodeInput.clear();
    await promoCodeInput.fill('VALID2024');
    await page.getByRole('button', { name: /apply/i }).click();

    // Verify error message is gone
    await expect(errorMessage).not.toBeVisible();
  });
});
